		return outgoing
				? new Counts(rows, rows > 0L ? 1L : 0L, rows > 0L ? 1L : 0L, distinctNeighbors)
				: new Counts(rows, distinctNeighbors, rows > 0L ? 1L : 0L, rows > 0L ? 1L : 0L);
